	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer l.Close()

	segments := l.Segments()
	var first, last uint64
	for i, s := range segments {
		if i == 0 || s.FirstSeq < first {
			first = s.FirstSeq
		}
		if s.LastSeq > last {
			last = s.LastSeq
		}
	}
	fmt.Printf("{\"segments\":%d,\"firstSeq\":%d,\"lastSeq\":%d}\n", len(segments), first, last)
}

