)

func runStat(t *testing.T, dir string) string {
	t.Helper()
	cmd := exec.Command("go", "run", ".", "--dir", dir, "stat")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("logctl stat: %v\n%s", err, out)
	}
	return string(out)
}

